/** All articles shown on the /articles hub, including the Fleet/Operating Lease cluster. */
export const allArticles: Article[] = [...articles, ...leaseArticles];

export function getArticle(slug: string): Article | undefined {
  return allArticles.find((a) => a.slug === slug);
}
